namespace Inventory;

/// <summary>Builds a replenishment plan across a set of stock items.</summary>
public sealed class ReplenishmentPlanner
{
    public IReadOnlyList<string> BuildPlan(IEnumerable<StockItem> items, ISupplier supplier, int season)
    {
        var plan = new List<string>();
        foreach (var item in items)
        {
            if (!TryGetOrder(item, season, out var sku, out var orderQuantity))
                continue;

            bool placed = supplier.PlaceOrder(sku, orderQuantity);
            plan.Add(FormatPlanEntry(sku, orderQuantity, placed));
        }

        return plan;
    }

    private static bool TryGetOrder(
        StockItem item,
        int season,
        out string sku,
        out int orderQuantity)
    {
        sku = string.Empty;
        orderQuantity = 0;

        if (item.OnHand < 0)
            return false;

        int available = item.OnHand - item.Reserved;
        if (available > item.ReorderPoint)
            return false;

        int deficit = item.ReorderPoint - available;
        orderQuantity = ApplySeasonalAdjustment(CalculateOrderQuantity(deficit), season);
        if (orderQuantity <= 0 || string.IsNullOrEmpty(item.Sku))
            return false;

        sku = item.Sku;
        return true;
    }

    private static int CalculateOrderQuantity(int deficit) => deficit switch
    {
        <= 0 => 0,
        < 10 => 10,
        < 100 => deficit,
        _ => deficit + 50
    };

    private static int ApplySeasonalAdjustment(int orderQuantity, int season) => season switch
    {
        4 when orderQuantity > 0 => (int)(orderQuantity * 1.5),
        1 => orderQuantity / 2,
        _ => orderQuantity
    };

    private static string FormatPlanEntry(string sku, int orderQuantity, bool placed)
    {
        if (!placed)
            return $"{sku}:FAILED";

        return orderQuantity > 200
            ? $"{sku}:LARGE:{orderQuantity}"
            : $"{sku}:{orderQuantity}";
    }
}
